import{_ as a,c as i,o as e,b0 as n}from"./chunks/framework.Becqh7-x.js";const l="/linux-dev-docs/assets/image-20230806105712227.Daqd_7Xd.png",p="/linux-dev-docs/assets/image-20230806105825987.COIg38pN.png",t="/linux-dev-docs/assets/image-20230806110708334.BU3RR4Ds.png",m=JSON.parse('{"title":"LV010-openssl","description":null,"frontmatter":{"title":"LV010-openssl","date":"2026-01-06T19:37:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/application/libs/126d2c6ecb4119afcea664fd","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T19:37:29.410Z","fulluuid":"fcea664fd7034944a2acf767c2f8e35a","useduuid":"fcea664fd"}},"headers":[],"relativePath":"sdoc/application/libs/126d2c6ecb4119afcea664fd.md","filePath":"sdoc/20-应用开发/90-第三方库移植/LV010-openssl.md","lastUpdated":1768604092000}'),r={name:"sdoc/application/libs/126d2c6ecb4119afcea664fd.md"};function h(o,s,d,c,k,u){return e(),i("div",null,[...s[0]||(s[0]=[n('<h1 id="lv010-openssl" tabindex="-1">LV010-openssl <a class="header-anchor" href="#lv010-openssl" aria-label="Permalink to &quot;LV010-openssl&quot;">​</a></h1><h2 id="一、openssl-简介" tabindex="-1">一、openssl 简介 <a class="header-anchor" href="#一、openssl-简介" aria-label="Permalink to &quot;一、openssl 简介&quot;">​</a></h2><h3 id="_1-它是什么" tabindex="-1">1. 它是什么？ <a class="header-anchor" href="#_1-它是什么" aria-label="Permalink to &quot;1. 它是什么？&quot;">​</a></h3><p>openssl 是一个安全套接字层密码库，囊括主要的密码算法、常用密钥、证书封装管理功能及实现 ssl 协议。openSSL 整个软件包大概可以分成三个主要的功能部分：SSL 协议库 libssl、应用程序命令工具以及密码算法库 libcrypto。</p><h3 id="_2-官网在哪" tabindex="-1">2. 官网在哪？ <a class="header-anchor" href="#_2-官网在哪" aria-label="Permalink to &quot;2. 官网在哪？&quot;">​</a></h3><p>它的官网在这里：<a href="https://www.openssl.org/" target="_blank" rel="noreferrer">/index.html (openssl.org)</a>。</p><h3 id="_3-源码下载" tabindex="-1">3. 源码下载 <a class="header-anchor" href="#_3-源码下载" aria-label="Permalink to &quot;3. 源码下载&quot;">​</a></h3><p>我们可以在这里找到下载的地方：<a href="https://www.openssl.org/source/" target="_blank" rel="noreferrer">/source/index.html (openssl.org)</a>。我直接选择下载的这个：</p><img src="'+l+'" alt="image-20230806105712227" style="zoom:50%;"><p>下载解压后会得到以下文件：</p><img src="'+p+`" alt="image-20230806105825987" style="zoom:50%;"><h2 id="二、移植-openssl" tabindex="-1">二、移植 openssl <a class="header-anchor" href="#二、移植-openssl" aria-label="Permalink to &quot;二、移植 openssl&quot;">​</a></h2><h3 id="_1-编译源码" tabindex="-1">1. 编译源码 <a class="header-anchor" href="#_1-编译源码" aria-label="Permalink to &quot;1. 编译源码&quot;">​</a></h3><p>我们进入刚才解压的 openssl 目录：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/5ALPHA/openssl-1.1.1v</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>然后我们通过以下命令配置、编译和安装 openssl：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/5ALPHA/openssl-1.1.1v/openssl_output</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Configure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-armv4</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shared</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> no-asm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix=/home/hk/5ALPHA/openssl-1.1.1v/openssl_output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CROSS_COMPILE=arm-linux-gnueabihf-</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>编译安装完成以后的 openssl 目录内容如图 :</p><img src="`+t+`" alt="image-20230806110708334" style="zoom:50%;"><p>然后将编译安装的目录中的 lib 目录是我们需要的，将 lib 目录下的 libcrypto 和 libssl 库拷贝到开发板根文件系统中的/usr/lib 目录下，命令如下</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/5ALPHA/openssl-1.1.1v/openssl_output/lib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -af</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libcrypto.so</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/4nfs/buildroot/usr/lib</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -af</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libssl.so</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/4nfs/buildroot/usr/lib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_2-测试库是否可用" tabindex="-1">2. 测试库是否可用 <a class="header-anchor" href="#_2-测试库是否可用" aria-label="Permalink to &quot;2. 测试库是否可用&quot;">​</a></h3><p>暂时没测，不过后边会一直 openssh，会用到这个库，可以相当于从那边侧面验证库知否可用了。</p>`,23)])])}const g=a(r,[["render",h]]);export{m as __pageData,g as default};
